1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.List;
7	import java.util.Map;
8	import net.officefloor.hq.app.Audit;
9	import net.officefloor.hq.app.person.Person;
10	import net.officefloor.hq.app.period.Period;
11	import net.officefloor.hq.app.period.PeriodRepository;
12	import net.officefloor.hq.app.person.PersonRepository;
13	import net.officefloor.hq.app.rate.Rate;
14	import net.officefloor.hq.app.rate.RateService;
15	import net.officefloor.hq.app.rollup.Rollup;
16	import net.officefloor.hq.app.setting.Role;
17	import net.officefloor.hq.app.setting.SettingService;
18	import net.officefloor.hq.app.sheet.SheetRepository;
19	import net.officefloor.hq.app.sheet.SheetService;
20	import org.springframework.http.HttpStatus;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	import org.springframework.web.server.ResponseStatusException;
24	
25	@Service
26	public class ClaimService {
27	
28	    private final ClaimRepository claims;
29	    private final PersonRepository people;
30	    private final RateService rates;
31	    private final SheetService sheets;
32	    private final SheetRepository sheetRows;
33	    private final PeriodRepository periods;
34	    private final SettingService settings;
35	    private final Rollup rollup;
36	    private final Audit audit;
37	
38	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
39	            SheetRepository sheetRows, PeriodRepository periods, SettingService settings, Rollup rollup,
40	            Audit audit) {
41	        this.claims = claims;
42	        this.people = people;
43	        this.rates = rates;
44	        this.sheets = sheets;
45	        this.sheetRows = sheetRows;
46	        this.periods = periods;
47	        this.settings = settings;
48	        this.rollup = rollup;
49	        this.audit = audit;
50	    }
51	
52	    /** The sheet's claims, newest first by their place in the list. */
53	    @Transactional(readOnly = true)
54	    public List<Claim> list(String sheetId) {
55	        return claims.findBySheetIdOrderByListedDesc(sheetId);
56	    }
57	
58	    /** Add a claim to a person; a claim with no date is dated the sheet's today. */
59	    @Transactional
60	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
61	            String corrects) {
62	        Person person = person(sheetId, personId);
63	        LocalDate dated = dateOr(sheetId, date);
64	        refuseIfClosed(sheetId, dated);
65	        refuseIfRetired(person, dated);
66	        refuseIfNotCorrecting(sheetId, personId, amount, corrects);
67	        Rollup.Snapshot before = rollup.snapshot(sheetId);
68	        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date.
69	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects,
70	                settings.terms(sheetId, person.gradeOn(dated)));
71	        // The sheet is locked (refuseIfClosed), so no other claim takes the same place.
72	        claim.setListed(claims.lastListed(sheetId) + 1);
73	        claim = claims.saveAndFlush(claim);
74	        recordChange("CLAIM_ADDED", user, person, claim);
75	        rollup.recordChanges(user, before);
76	        return claim;
77	    }
78	
79	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
80	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. */
81	    @Transactional
82	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
83	            String corrects) {
84	        Claim claim = claims.findForUpdate(id, sheetId)
85	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
86	        LocalDate dated = dateOr(sheetId, date);
87	        refuseIfClosed(sheetId, claim.getDate());
88	        refuseIfClosed(sheetId, dated);
89	        if (claim.getStatus() != ClaimStatus.DRAFT) {
90	            throw new ResponseStatusException(HttpStatus.CONFLICT,
91	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
92	        }
93	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
94	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
95	        Rollup.Snapshot before = rollup.snapshot(sheetId);
96	        claim.set(amount, dated, noteOf(note), corrects);
97	        Claim saved = claims.saveAndFlush(claim);
98	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
99	        rollup.recordChanges(user, before);
100	        return saved;
101	    }
102	
103	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
104	     *  by the user who opened the claim. A clerk's settling of a claim whose due is above the sheet's
105	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
106	     *  steward settles anything). */
107	    @Transactional
108	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
109	        Claim claim = claims.findForUpdate(id, sheetId)
110	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
111	        refuseIfClosed(sheetId, claim.getDate());
112	        if (!claim.getStatus().canBecome(next)) {
113	            throw new ResponseStatusException(HttpStatus.CONFLICT,
114	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
115	        }
116	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
117	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
118	                    "The user who opened a claim cannot settle it.");
119	        }
120	        Person person = person(sheetId, claim.getPersonId());
121	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
122	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
123	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
124	        Rollup.Snapshot before = rollup.snapshot(sheetId);
125	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
126	        claim.setStatus(next);
127	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
128	        // A voided claim keeps its number, which is never given to another claim.
129	        claim.setNumber(number);
130	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
131	        Claim saved = claims.saveAndFlush(claim);
132	        String event = EVENTS.get(next);
133	        if (next == ClaimStatus.SETTLED) {
134	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
135	        } else {
136	            recordChange(event, user, person, saved, number, "");
137	        }
138	        rollup.recordChanges(user, before);
139	        return saved;
140	    }
141	
142	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
143	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
144	     *  its new person's next statement). Refused unless the user is a steward of the sheet, and for a
145	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
146	     *  or to a person retired by the claim's date. */
147	    @Transactional
148	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
149	        Claim claim = claims.findForUpdate(id, sheetId)
150	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
151	        refuseIfClosed(sheetId, claim.getDate());
152	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
153	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward moves a claim to another person.");
154	        }
155	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT,
157	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
158	        }
159	        Person from = person(sheetId, claim.getPersonId());
160	        Person to = person(sheetId, toPersonId);
161	        if (from.getId().equals(to.getId())) {
162	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
163	        }
164	        refuseIfRetired(to, claim.getDate());
165	        Rollup.Snapshot before = rollup.snapshot(sheetId);
166	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
167	        Claim saved = claims.saveAndFlush(claim);
168	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
169	                " from=" + from.getName() + " to=" + to.getName());
170	        rollup.recordChanges(user, before);
171	        return saved;
172	    }
173	
174	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
175	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
176	    @Transactional
177	    public Claim approve(String sheetId, String user, long id) {
178	        Claim claim = pending(sheetId, user, id);
179	        if (user.equals(claim.getOpenedBy())) {
180	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
181	                    "The user who opened a claim cannot approve it.");
182	        }
183	        Person person = person(sheetId, claim.getPersonId());
184	        BigDecimal dueNow = due(sheetId, person, claim);
185	        Rollup.Snapshot before = rollup.snapshot(sheetId);
186	        claim.setStatus(ClaimStatus.SETTLED);
187	        claim.setSettledDue(dueNow);
188	        Claim saved = claims.saveAndFlush(claim);
189	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
190	        rollup.recordChanges(user, before);
191	        return saved;
192	    }
193	
194	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
195	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
196	    @Transactional
197	    public Claim reject(String sheetId, String user, long id, String reason) {
198	        Claim claim = pending(sheetId, user, id);
199	        Person person = person(sheetId, claim.getPersonId());
200	        Rollup.Snapshot before = rollup.snapshot(sheetId);
201	        claim.setStatus(ClaimStatus.OPEN);
202	        Claim saved = claims.saveAndFlush(claim);
203	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
204	        rollup.recordChanges(user, before);
205	        return saved;
206	    }
207	
208	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
209	     *  dated inside a closed period, or the user is not a steward of the sheet. */
210	    private Claim pending(String sheetId, String user, long id) {
211	        Claim claim = claims.findForUpdate(id, sheetId)
212	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
213	        refuseIfClosed(sheetId, claim.getDate());
214	        if (claim.getStatus() != ClaimStatus.PENDING) {
215	            throw new ResponseStatusException(HttpStatus.CONFLICT,
216	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
217	        }
218	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
219	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
220	        }
221	        return claim;
222	    }
223	
224	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
225	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
226	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
227	
228	    private static String text(BigDecimal due) {
229	        return due == null ? "n/a" : due.toPlainString();
230	    }
231	
232	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
233	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
234	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
235	    private String nextNumber(String sheetId, Claim claim) {
236	        LocalDate from = settings.periodNumberingFrom(sheetId);
237	        if (from == null || sheets.today(sheetId).isBefore(from)) {
238	            return Integer.toString(sheets.nextClaimNumber(sheetId));
239	        }
240	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
241	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
242	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
243	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
244	    }
245	
246	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
247	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
248	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
249	        BigDecimal limit = settings.clerkLimit(sheetId);
250	        return limit != null && due.compareTo(limit) > 0;
251	    }
252	
253	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
254	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
255	    private void refuseIfClosed(String sheetId, LocalDate date) {
256	        sheetRows.findForUpdate(sheetId);
257	        if (periods.isClosedOn(sheetId, date)) {
258	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
259	        }
260	    }
261	
262	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
263	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
264	        if (amount.signum() >= 0) return;
265	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
266	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
267	        if (!settled) {
268	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
269	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
270	        }
271	    }
272	
273	    /** Refuse a claim dated after its person's retirement date. */
274	    private static void refuseIfRetired(Person person, LocalDate date) {
275	        if (person.isRetiredOn(date)) {
276	            throw new ResponseStatusException(HttpStatus.CONFLICT,
277	                    "The claim is dated after " + person.getName() + " retired.");
278	        }
279	    }
280	
281	    private Person person(String sheetId, long personId) {
282	        return people.findByIdAndSheetId(personId, sheetId)
283	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
284	    }
285	
286	    /** What is due on the claim now: its figure with the late charge on top while it is open and
